package br.com.casamento;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.OffsetDateTime;
import java.util.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.client.RestClient;
import org.springframework.web.server.ResponseStatusException;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
@RestController @RequestMapping("/api") public class Api {
 private final NamedParameterJdbcTemplate db; private final RestClient http=RestClient.create("https://api.mercadopago.com");
 @Value("${app.mp.access-token:}") String mpAccessToken; @Value("${app.mp.public-key:}") String mpPublicKey; @Value("${app.mp.webhook-secret:}") String mpWebhookSecret;
 Api(NamedParameterJdbcTemplate db){this.db=db;}
 record Rsvp(@NotBlank @Size(min=3,max=160) String name,@Size(max=40) String phone,@Email @Size(max=200) String email,@Pattern(regexp="yes|no") String attending,@Min(0) @Max(20) int adults,@Min(0) @Max(20) int children,@Size(max=500) String note){}
 record Message(@NotBlank @Size(max=160) String name,@NotBlank @Size(max=1000) String text){}
 record Pledge(@NotNull UUID giftId,@NotBlank @Size(max=160) String name,@Size(max=300) String message,@NotNull @DecimalMin("1.00") @DecimalMax("100000.00") BigDecimal amount){}
 record Gift(@NotBlank @Size(max=160) String name,@NotNull @DecimalMin("1.00") BigDecimal price,@NotBlank @Size(max=80) String category,@Size(max=1000) String image){}
 record CardPayment(@NotNull UUID giftId,@NotBlank @Size(max=160) String name,@Email @NotBlank @Size(max=200) String email,@Size(max=300) String message,@NotBlank String token,@NotBlank String paymentMethodId,String issuerId,@NotNull @Min(1) @Max(24) Integer installments,String identificationType,@Size(max=32) String identificationNumber){}
 private MapSqlParameterSource p(Object... pairs){MapSqlParameterSource s=new MapSqlParameterSource();for(int i=0;i<pairs.length;i+=2)s.addValue((String)pairs[i],pairs[i+1]);return s;}
 private List<Map<String,Object>> list(String sql){return db.queryForList(sql,new MapSqlParameterSource());}
 @GetMapping("/config") Map<String,String> config(@Value("${app.pix.key}") String key,@Value("${app.pix.name}") String name,@Value("${app.pix.bank}") String bank){return Map.of("pixKey",key,"pixName",name,"pixBank",bank,"mpPublicKey",mpPublicKey==null?"":mpPublicKey);}
 @GetMapping("/gifts") List<Map<String,Object>> gifts(){return list("select id,name,price,category,image from gifts order by name");}
 @GetMapping("/messages") List<Map<String,Object>> messages(){return list("select id,name,text,approved,created_at as \"createdAt\" from messages where approved=true order by created_at desc limit 100");}
 @PostMapping("/rsvp") ResponseEntity<Map<String,Object>> rsvp(@Valid @RequestBody Rsvp r){if(r.attending()==null||r.attending().equals("yes")&&(r.adults()<1||r.adults()+r.children()>30)||r.attending().equals("no")&&(r.adults()!=0||r.children()!=0))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Quantidade inválida");UUID id=UUID.randomUUID();db.update("insert into guests(id,name,phone,email,attending,adults,children,note) values(:id,:name,:phone,:email,:attending,:adults,:children,:note)",p("id",id,"name",r.name().trim(),"phone",r.phone(),"email",r.email(),"attending",r.attending(),"adults",r.adults(),"children",r.children(),"note",r.note()));return ResponseEntity.status(201).body(Map.of("id",id,"saved",true));}
 @PostMapping("/messages") ResponseEntity<Map<String,Object>> message(@Valid @RequestBody Message m){UUID id=UUID.randomUUID();db.update("insert into messages(id,name,text) values(:id,:name,:text)",p("id",id,"name",m.name().trim(),"text",m.text().trim()));return ResponseEntity.status(201).body(Map.of("id",id,"saved",true));}
 @PostMapping("/pledges") ResponseEntity<Map<String,Object>> pledge(@Valid @RequestBody Pledge r){List<Map<String,Object>> found=db.queryForList("select name from gifts where id=:id",p("id",r.giftId()));if(found.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Presente não encontrado");UUID id=UUID.randomUUID();db.update("insert into pledges(id,gift_id,gift,amount,name,message) values(:id,:giftId,:gift,:amount,:name,:message)",p("id",id,"giftId",r.giftId(),"gift",found.get(0).get("name"),"amount",r.amount(),"name",r.name().trim(),"message",r.message()));return ResponseEntity.status(201).body(Map.of("id",id,"status","pending"));}
 @PostMapping("/payments/card") ResponseEntity<Map<String,Object>> cardPayment(@Valid @RequestBody CardPayment r){if(mpAccessToken==null||mpAccessToken.isBlank())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Pagamento por cartão indisponível no momento.");List<Map<String,Object>> found=db.queryForList("select id,name,price from gifts where id=:id",p("id",r.giftId()));if(found.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Presente indisponível");Map<String,Object> gift=found.get(0);BigDecimal price=(BigDecimal)gift.get("price");UUID pledgeId=UUID.randomUUID(),paymentId=UUID.randomUUID();String idempotency=UUID.randomUUID().toString();db.update("insert into pledges(id,gift_id,gift,amount,name,message,status) values(:id,:giftId,:gift,:amount,:name,:message,'pending')",p("id",pledgeId,"giftId",r.giftId(),"gift",gift.get("name"),"amount",price,"name",r.name().trim(),"message",r.message()));db.update("insert into payments(id,pledge_id,gift_id,gift,payer_name,payer_email,amount,payment_method,installments,mp_status,idempotency_key) values(:id,:pledgeId,:giftId,:gift,:name,:email,:amount,'credit_card',:installments,'creating',:idem)",p("id",paymentId,"pledgeId",pledgeId,"giftId",r.giftId(),"gift",gift.get("name"),"name",r.name().trim(),"email",r.email().trim(),"amount",price,"installments",r.installments(),"idem",idempotency));Map<String,Object> payer=new LinkedHashMap<>();payer.put("email",r.email().trim());if(r.identificationType()!=null&&!r.identificationType().isBlank()&&r.identificationNumber()!=null&&!r.identificationNumber().isBlank())payer.put("identification",Map.of("type",r.identificationType(),"number",r.identificationNumber().replaceAll("\\D","")));Map<String,Object> body=new LinkedHashMap<>();body.put("transaction_amount",price);body.put("token",r.token());body.put("description","Presente de casamento - "+gift.get("name"));body.put("installments",r.installments());body.put("payment_method_id",r.paymentMethodId());if(r.issuerId()!=null&&!r.issuerId().isBlank())body.put("issuer_id",r.issuerId());body.put("payer",payer);body.put("external_reference",paymentId.toString());try{Map res=http.post().uri("/v1/payments").header("Authorization","Bearer "+mpAccessToken).header("X-Idempotency-Key",idempotency).contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(Map.class);applyPayment(paymentId,res);return ResponseEntity.status(201).body(publicPayment(res));}catch(Exception e){db.update("update payments set mp_status='failed', mp_status_detail=:detail, updated_at=now() where id=:id",p("id",paymentId,"detail","creation_failed"));throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Não foi possível processar o pagamento. Tente novamente em alguns minutos.");}}
 @PostMapping("/webhooks/mercadopago") ResponseEntity<Void> mpWebhook(@RequestHeader(value="x-signature",required=false) String sig,@RequestHeader(value="x-request-id",required=false) String req,@RequestBody Map<String,Object> body){Object dataObj=body.get("data");String dataId=dataObj instanceof Map<?,?> m?String.valueOf(m.get("id")):null;if(dataId==null)return ResponseEntity.ok().build();if(mpWebhookSecret!=null&&!mpWebhookSecret.isBlank()&&!validWebhook(sig,req,dataId))return ResponseEntity.status(401).build();try{Map res=http.get().uri("/v1/payments/"+dataId).header("Authorization","Bearer "+mpAccessToken).retrieve().body(Map.class);List<Map<String,Object>> rows=db.queryForList("select id from payments where mp_payment_id=:mp",p("mp",String.valueOf(res.get("id"))));if(rows.isEmpty()){String ext=String.valueOf(res.get("external_reference"));if(ext!=null&&!ext.equals("null"))applyPayment(UUID.fromString(ext),res);}else applyPayment((UUID)rows.get(0).get("id"),res);}catch(Exception ignored){}return ResponseEntity.ok().build();}
 private boolean validWebhook(String sig,String req,String dataId){try{if(sig==null||req==null)return false;Map<String,String> parts=new HashMap<>();for(String part:sig.split(",")){String[] kv=part.split("=",2);if(kv.length==2)parts.put(kv[0].trim(),kv[1].trim());}String ts=parts.get("ts"),v1=parts.get("v1");if(ts==null||v1==null)return false;Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(mpWebhookSecret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));byte[] digest=mac.doFinal(("id:"+dataId+";request-id:"+req+";ts:"+ts+";").getBytes(StandardCharsets.UTF_8));String expected=HexFormat.of().formatHex(digest);return MessageDigest.isEqual(expected.getBytes(StandardCharsets.UTF_8),v1.getBytes(StandardCharsets.UTF_8));}catch(Exception e){return false;}}
 private Map<String,Object> publicPayment(Map res){String status=String.valueOf(res.get("status"));return Map.of("id",String.valueOf(res.get("id")),"status",status,"statusDetail",String.valueOf(res.get("status_detail")),"approved","approved".equals(status));}
 private void applyPayment(UUID id,Map res){String status=String.valueOf(res.get("status"));String detail=String.valueOf(res.get("status_detail"));Object mp=res.get("id"),charged=res.get("transaction_amount"),approved=res.get("date_approved");db.update("update payments set mp_payment_id=:mp, mp_status=:status, mp_status_detail=:detail, charged_amount=:charged, approved_at=case when :approved is not null and :approved <> 'null' then cast(:approved as timestamptz) else approved_at end, updated_at=now() where id=:id",p("id",id,"mp",String.valueOf(mp),"status",status,"detail",detail,"charged",charged,"approved",approved==null?null:String.valueOf(approved)));if("approved".equals(status))db.update("update pledges set status='confirmed' where id=(select pledge_id from payments where id=:id)",p("id",id));}
 @GetMapping("/admin/check") Map<String,Boolean> check(){return Map.of("ok",true);}
 @GetMapping("/admin/guests") List<Map<String,Object>> guests(){return list("select id,name,phone,email,attending,adults,children,note,created_at as \"createdAt\" from guests order by created_at desc");}
 @GetMapping("/admin/messages") List<Map<String,Object>> allMessages(){return list("select id,name,text,approved,created_at as \"createdAt\" from messages order by created_at desc");}
 @GetMapping("/admin/pledges") List<Map<String,Object>> pledges(){return list("select id,gift_id as \"giftId\",gift,amount,name,message,status,created_at as \"createdAt\" from pledges order by created_at desc");}
 @GetMapping("/admin/payments") List<Map<String,Object>> payments(){return list("select id,gift,payer_name as \"payerName\",payer_email as \"payerEmail\",amount,charged_amount as \"chargedAmount\",payment_method as \"paymentMethod\",installments,mp_payment_id as \"mpPaymentId\",mp_status as \"status\",mp_status_detail as \"statusDetail\",created_at as \"createdAt\",approved_at as \"approvedAt\",updated_at as \"updatedAt\" from payments order by created_at desc");}
 @PostMapping("/admin/gifts") ResponseEntity<Map<String,Object>> addGift(@Valid @RequestBody Gift g){UUID id=UUID.randomUUID();db.update("insert into gifts(id,name,price,category,image) values(:id,:name,:price,:category,:image)",p("id",id,"name",g.name(),"price",g.price(),"category",g.category(),"image",g.image()));return ResponseEntity.status(201).body(Map.of("id",id));}
 @PatchMapping("/admin/gifts/{id}") void updateGift(@PathVariable UUID id,@Valid @RequestBody Gift g){db.update("update gifts set name=:name,price=:price,category=:category,image=:image where id=:id",p("id",id,"name",g.name(),"price",g.price(),"category",g.category(),"image",g.image()));}
 @PatchMapping("/admin/messages/{id}/approval") void approve(@PathVariable UUID id,@RequestBody Map<String,Boolean> body){db.update("update messages set approved=:approved where id=:id",p("approved",Boolean.TRUE.equals(body.get("approved")),"id",id));}
 @PatchMapping("/admin/pledges/{id}/status") void status(@PathVariable UUID id,@RequestBody Map<String,String> body){String status=body.get("status");if(!List.of("pending","confirmed").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);db.update("update pledges set status=:status where id=:id",p("status",status,"id",id));}
 @DeleteMapping("/admin/{type}/{id}") void delete(@PathVariable String type,@PathVariable UUID id){String table=switch(type){case "guests"->"guests";case "messages"->"messages";case "pledges"->"pledges";case "gifts"->"gifts";case "payments"->"payments";default->throw new ResponseStatusException(HttpStatus.NOT_FOUND);};db.update("delete from "+table+" where id=:id",p("id",id));}
}
